-- Migración: Seed Tercer Tiempo web -> FutPro Manager
-- Ligas: Primera Fuerza Especial (Liga Luis Pirata Fuente) y Primera A Temporada 2026
-- Fuente: TercerTiempo_web/src/data/quarterfinals.js, primeraA.js, resultados_primera_fuerza_especial.json
-- Nota: standings oficiales solo traen Pts/Dif/JJ, sin W/D/L/GF/GA detallados.
-- Se preservan Pts/Dif/JJ oficiales y se estima desglose W/D/L/GF/GA válido para constraints.
-- Los partidos cargados (J17, Cuartos ida/vuelta, J29) disparan el trigger de recálculo;
-- por eso al final se hace upsert de standings oficiales para monitoreo.

-- 0. Ligas
on conflict (slug) do update set
  name = excluded.name,
  description = excluded.description,
  is_public = excluded.is_public,
  status = excluded.status,
  updated_at = now();

-- 1. Temporadas 2026
on conflict (league_id, slug) do update set
  name = excluded.name, start_date = excluded.start_date, end_date = excluded.end_date, status = excluded.status;

-- 2. Equipos Primera Fuerza Especial (18, nombres normalizados)
on conflict (league_id, slug) do update set name = excluded.name, status='active';

-- 3. Equipos Primera A (20)
on conflict (league_id, slug) do update set name = excluded.name, status='active';

-- 4. Sedes (cuartos ida)
on conflict do nothing;

-- 5. Partidos J17 Primera Fuerza Especial (regular_season, completed)
-- Uso equipo_id via subselect por slug para idempotencia: se borran e insertan los de round J-17 para evitar duplicados.
delete from public.matches
where season_id = (select s.id from public.seasons s join public.leagues l on l.id=s.league_id where l.slug='primera-fuerza-especial' and s.slug='temporada-2026')
  and round_name = 'Jornada 17';


-- 6. Cuartos de final ida/vuelta (quarter_finals)
delete from public.matches
where season_id = (select s.id from public.seasons s join public.leagues l on l.id=s.league_id where l.slug='primera-fuerza-especial' and s.slug='temporada-2026')
  and stage = 'quarter_finals';


-- 7. Partidos J29 Primera A
delete from public.matches
where season_id = (select s.id from public.seasons s join public.leagues l on l.id=s.league_id where l.slug='primera-a' and s.slug='temporada-2026')
  and round_name like 'Jornada 29%';


-- 8. Standings oficiales (upsert post-trigger para monitoreo)
-- Especial J17: played 17, pts/dif oficiales
on conflict (season_id, team_id) do update set
  played=excluded.played, won=excluded.won, drawn=excluded.drawn, lost=excluded.lost,
  goals_for=excluded.goals_for, goals_against=excluded.goals_against,
  goal_difference=excluded.goal_difference, points=excluded.points, updated_at=now();

-- Primera A pre-J29: JJ/Dif/Pts oficiales
on conflict (season_id, team_id) do update set
  played=excluded.played, won=excluded.won, drawn=excluded.drawn, lost=excluded.lost,
  goals_for=excluded.goals_for, goals_against=excluded.goals_against,
  goal_difference=excluded.goal_difference, points=excluded.points, updated_at=now();
